from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != bg or (sr, sc) in seen:
                continue
            comp = {(sr, sc)}
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            while q:
                r, c = q.popleft()
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); comp.add((nr,nc)); q.append((nr,nc))
            minr, maxr = min(r for r,c in comp), max(r for r,c in comp)
            minc, maxc = min(c for r,c in comp), max(c for r,c in comp)
            if len(comp) != (maxr-minr+1)*(maxc-minc+1):
                continue
            # Components wholly inside the frame are holes. Edge-touching
            # components are holes only when every edge run is capped by outline.
            valid = True
            for coords in ([(0,c) for c in range(w)], [(h-1,c) for c in range(w)],
                           [(r,0) for r in range(h)], [(r,w-1) for r in range(h)]):
                i = 0
                while i < len(coords):
                    if coords[i] not in comp:
                        i += 1; continue
                    start = i
                    while i+1 < len(coords) and coords[i+1] in comp:
                        i += 1
                    end = i
                    left_capped = start > 0 and grid[coords[start-1][0]][coords[start-1][1]] != bg
                    right_capped = end+1 < len(coords) and grid[coords[end+1][0]][coords[end+1][1]] != bg
                    if not (left_capped and right_capped):
                        valid = False
                    i += 1
            if valid:
                for r,c in comp:
                    out[r][c] = 4
    return out

